// Daytona USA -- D3D9 call tracer (phase 0; retained as an opt-in instrument)
//
// GENERATED by ../_tools/daytona_d3d9_sigscan/gen_trace.py -- OUTSIDE this repo,
// in the shared projects/_tools tree, so it is not reachable from a fresh clone.
// It still exists; regeneration is possible, it just needs that tree.
//
// Pass-through instrumentation over the guest's statically-linked Xbox 360 D3D9.
// Every hook records and then calls __imp__ through, so a traced run is
// behaviourally identical. Purpose: turn the static sig-scan map (which entry
// points are *reachable*) into a runtime profile (which actually *fire*, how
// often, with what arguments) before any renderer work begins.
//
// That purpose is served -- the renderer is built. The profiling is now off
// unless DT_TRACE_D3D9=1; only call counting still runs by default, to keep the
// positive control alive. See Record().
#pragma once

#include <cstddef>
#include <cstdint>

#include <rex/ppc/context.h>

namespace dt_d3d9_trace {

struct Entry {
    uint32_t    addr;          // guest address
    const char* sym;           // sub_XXXXXXXX
    const char* name;          // D3D9 symbol from XDK 20500 d3d9.lib, "" if unidentified
    uint16_t    ninsn;
    uint16_t    game_callers;  // distinct game functions that call it (static)
};

inline constexpr size_t kEntryCount = 125;
extern const Entry kEntries[kEntryCount];

// Recorded on every intercepted call. Cheap by DEFAULT: two relaxed atomic
// increments. Under DT_TRACE_D3D9=1 it additionally does first-call argument
// capture, four argument histograms and per-draw call-order capture -- which is
// emphatically not cheap, and is why it is opt-in.
void Record(size_t index, const PPCContext& ctx);

// Emit the profile to the log. Called periodically and on shutdown.
// Fails LOUDLY if the positive-control entry points never fired -- a silent
// all-zero table would otherwise be indistinguishable from "hooks not linked".
// Logged at WARN, not INFO: the shipped daytona.ini sets log_level=warn, and an
// INFO-level dump is silently swallowed there.
void Dump(const char* reason);

// Called from the existing D3DDevice_Swap hook in stubs.cpp. Drives dumps off a
// real frame tick rather than call volume, so the cadence holds even when few
// calls are intercepted -- and the frame count is a second positive control: if
// it stays 0 the game never presented, so an empty call table says nothing about
// D3D9 usage.
void OnFrame();

}  // namespace dt_d3d9_trace
